const r = await tools.mcp__executor_personal__execute({code: `
const getProject = await tools.vercel_api.user.personalvercelapi.projects.getProject({
  idOrName: "bundjil-codex-proxy"
});
if (!getProject.ok) return { ok: false, stage: "project", code: getProject.error.code };

const project = getProject.data;
const envResult = await tools.vercel_api.user.personalvercelapi.projects.filterProjectEnvs({
  idOrName: "bundjil-codex-proxy",
  decrypt: "false"
});
if (!envResult.ok) return { ok: false, stage: "env", code: envResult.error.code };

const rawEnvs = Array.isArray(envResult.data)
  ? envResult.data
  : ("envs" in envResult.data ? envResult.data.envs : [envResult.data]);
const normalizeTargets = (target) =>
  Array.isArray(target) ? target : target ? [target] : [];
const selectedPrefixes = ["BUNDJIL_", "UPSTASH_REDIS_REST_", "KV_REST_API_"];
const envs = rawEnvs
  .filter((env) => selectedPrefixes.some((prefix) => env.key.startsWith(prefix)))
  .map((env) => ({
    key: env.key,
    targets: normalizeTargets(env.target).sort(),
    type: env.type,
    integrationBacked: Boolean(env.configurationId || env.contentHint),
    contentHintType: env.contentHint?.type ?? null
  }))
  .sort((a, b) => a.key.localeCompare(b.key));

const deploymentsResult = await tools.vercel_api.user.personalvercelapi.deployments.getDeployments({
  projectId: project.id,
  limit: 20
});
if (!deploymentsResult.ok) return { ok: false, stage: "deployments", code: deploymentsResult.error.code };
const previews = deploymentsResult.data.deployments
  .filter((deployment) => deployment.target !== "production")
  .sort((a, b) => (b.createdAt ?? b.created) - (a.createdAt ?? a.created));
const productions = deploymentsResult.data.deployments
  .filter((deployment) => deployment.target === "production")
  .sort((a, b) => (b.createdAt ?? b.created) - (a.createdAt ?? a.created));

const integrationsResult = await tools.vercel_api.user.personalvercelapi.integrations.getConfigurations({
  view: "account",
  installationType: "marketplace"
});
const configurations = integrationsResult.ok && Array.isArray(integrationsResult.data)
  ? integrationsResult.data
  : [];
const matchingIntegrations = configurations
  .filter((configuration) => configuration.projects?.includes(project.id))
  .map((configuration) => ({
    slug: configuration.slug ?? null,
    status: configuration.status ?? null,
    installationType: configuration.installationType ?? null
  }));

return {
  ok: true,
  source: "Executor Personal Vercel API; no teamId or external scope supplied",
  project: {
    name: project.name,
    rootDirectory: project.rootDirectory ?? null,
    framework: project.framework ?? null,
    buildCommand: project.buildCommand ?? null,
    outputDirectory: project.outputDirectory ?? null,
    installCommand: project.installCommand ?? null,
    nodeVersion: project.nodeVersion
  },
  envs,
  integrationCount: project.integrations?.length ?? 0,
  matchingIntegrations,
  latestPreview: previews[0] ? {
    state: previews[0].readyState ?? previews[0].state ?? null,
    createdAt: previews[0].createdAt ?? previews[0].created,
    target: previews[0].target ?? null,
    source: previews[0].source ?? null
  } : null,
  latestProduction: productions[0] ? {
    state: productions[0].readyState ?? productions[0].state ?? null,
    createdAt: productions[0].createdAt ?? productions[0].created,
    target: productions[0].target
  } : null
};
`});
text(r);

