const r = await tools.mcp__executor_personal__execute({code: `
const projectName = "bundjil-codex-proxy";
const desired = [
  { key: "BUNDJIL_CODEX_PROFILE_ID", value: "default", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_CONNECTOR_ID", value: "bundjil-local", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_INSTALLATION_ID", value: "agent-dev", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_SUBJECT_ID", value: "personal-owner", type: "plain", target: ["preview"] }
];

const write = await tools.vercel_api.user.personalvercelapi.projects.createProjectEnv({
  idOrName: projectName,
  upsert: "true",
  body: desired
});
if (!write.ok) {
  return { ok: false, stage: "upsert", code: write.error.code };
}

const metadata = await tools.vercel_api.user.personalvercelapi.projects.filterProjectEnvs({
  idOrName: projectName,
  decrypt: "false"
});
if (!metadata.ok) {
  return { ok: false, stage: "metadata-readback", code: metadata.error.code };
}

const rawEnvs = Array.isArray(metadata.data)
  ? metadata.data
  : ("envs" in metadata.data ? metadata.data.envs : [metadata.data]);
const normalizeTargets = (target) =>
  (Array.isArray(target) ? target : target ? [target] : []).slice().sort();
const expectedKeys = desired.map((entry) => entry.key).sort();
const expectedMetadata = rawEnvs
  .filter((env) => expectedKeys.includes(env.key))
  .map((env) => ({ key: env.key, targets: normalizeTargets(env.target), type: env.type }))
  .sort((a, b) => a.key.localeCompare(b.key));
const allBundjilMetadata = rawEnvs
  .filter((env) => env.key.startsWith("BUNDJIL_"))
  .map((env) => ({ key: env.key, targets: normalizeTargets(env.target) }))
  .sort((a, b) => a.key.localeCompare(b.key));
const productionBundjilKeys = allBundjilMetadata
  .filter((env) => env.targets.includes("production"))
  .map((env) => env.key);
const developmentDesiredKeys = expectedMetadata
  .filter((env) => env.targets.includes("development"))
  .map((env) => env.key);
const productionDesiredKeys = expectedMetadata
  .filter((env) => env.targets.includes("production"))
  .map((env) => env.key);
const created = Array.isArray(write.data.created) ? write.data.created : [write.data.created];

return {
  ok: write.data.failed.length === 0,
  action: {
    requested: desired.length,
    acknowledged: created.length,
    failed: write.data.failed.map((item) => ({
      key: item.error.key ?? item.error.envVarKey ?? null,
      code: item.error.code
    }))
  },
  readback: {
    project: projectName,
    expectedMetadata,
    allExpectedPresent: expectedMetadata.length === expectedKeys.length &&
      expectedMetadata.every((env) => env.targets.length === 1 && env.targets[0] === "preview"),
    developmentDesiredKeys,
    productionDesiredKeys,
    productionBundjilKeys
  },
  source: "Executor Personal Vercel API; no teamId or external scope supplied"
};
`});
